styleFragments:
background: rgba(255, 255, 255, 0.7);
backdrop-filter: blur(4px) saturate(6) brightness(1.05);
box-shadow: 0 8px 32px rgba(0, 0, 0, 0.09);

::before {
      box-shadow: inset 0 0 8px
      var(--tui-background-ios-liquid-glass-glow);
      opacity: 0.1;
    }

:after {
      padding: 1px;
      background: var(--tui-background-button-ios-liquid-glass-bevel-gradient);
      mask-image: linear-gradient(#000 0 0), linear-gradient(#000 0 0);
      mask-origin: content-box, border-box;
      mask-clip: content-box, border-box;
      /* stylelint-disable-next-line */
      -webkit-mask-composite: xor;
      mask-composite: exclude;
      filter: brightness(1.05);
}

.container {
    color: var(--tui-text-ios-liquid-glass);
    display: flex;
    flex-flow: row nowrap;
    align-items: center;
    gap: 4px;
    border-radius: var(--t-appbar-height);
    height: var(--t-appbar-height);
    background: var(--tui-background-ios-liquid-glass);
    backdrop-filter: blur(4px) saturate(1.3) brightness(1.05);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.09);
    position: relative;
    justify-content: center;
    transition: transform var(--tui-animation-duration-fast) var(--tui-animation-curve-expressive-entrance),
      background-color var(--tui-animation-duration-fastest) ease, color var(--tui-animation-duration-fastest) ease,
      box-shadow var(--tui-animation-duration-fastest) ease, backdrop-filter var(--tui-animation-duration-fastest) ease;

:active {
      transform: scale(1.25);
      filter: brightness(1.5);
      background: rgb(from var(--tui-background-ios-liquid-glass) r g b / 0.3);   
}

@keyframes appbar-enter-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes appbar-icon-deblur {
  from {
    filter: blur(16px);
    -webkit-filter: blur(16px);
  }
  to {
    filter: blur(0);
    -webkit-filter: blur(0);
  }
}

.step {
  position: absolute;
  z-index: calc(-1 * var(--t-step));
  top: 0;
  left: 0;
  width: 100%;
  height: calc(120px - 6px * var(--t-step));
  backdrop-filter: blur(calc(0.06px * var(--t-step)));
  will-change: backdrop-filter;
  border-radius: var(--bottom-sheet-border-radius);
}
